<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Domain;

use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Holder\SnippetUidAttributeHolder;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Holder\SnippetCodeAttributeHolder;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Holder\SnippetTenantAttributeHolder;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Holder\SnippetEnabledAttributeHolder;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Holder\SnippetVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class SnippetAttributes
{
    use SnippetUidAttributeHolder;
    use SnippetCodeAttributeHolder;
    use SnippetTenantAttributeHolder;
    use SnippetEnabledAttributeHolder;
    use SnippetVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'code' => 'unsetCode',
      'tenant' => 'unsetTenant',
      'enabled' => 'unsetEnabled',
      'version' => 'unsetVersion',
    ];

    public function createNewInstance(): Snippet
    {
        $errors = new ConstraintFailList();
        $uid = $this->uidTryBuildInitial($errors);
        $code = $this->codeTryBuildInitial($errors);
        $tenant = $this->tenantTryBuildInitial($errors);
        $enabled = $this->enabledTryBuildInitial($errors);
        $version = $this->versionTryBuildInitial($errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($code !== null);
        return new Snippet(
            uid: $uid,
            code: $code,
            tenant: $tenant,
            enabled: $enabled,
            version: $version,
        );
    }
    public function withAssertedRules(): SnippetAttributes
    {
        $value = new SnippetAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedCodeRules($value, $errorsList);
        $this->withAssertedTenantRules($value, $errorsList);
        $this->withAssertedEnabledRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): SnippetAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultCode();
        $this->withDefaultTenant();
        $this->withDefaultEnabled();
        $this->withDefaultVersion();
        return $this;
    }
}
